from itertools import product

def solve(facts):
    alphabet = tuple(sorted(set(facts['alphabet'])))
    length = facts['length']
    modulus = facts['modulus']
    residue = facts['residue']
    low, high = facts['sum_min'], facts['sum_max']
    target, required = facts['target_digit'], facts['target_count']
    states = {(-1, 0, 0, 0): 1}
    for position in range(length):
        following = {}
        remaining = length - position - 1
        for (last, remainder, total, copies), ways in states.items():
            for digit in alphabet:
                if digit == last:
                    continue
                new_total = total + digit
                new_copies = copies + int(digit == target)
                if new_total > high or new_copies > required or new_copies + remaining < required:
                    continue
                key = (digit, (remainder * 10 + digit) % modulus, new_total, new_copies)
                following[key] = following.get(key, 0) + ways
        states = following
    count = 0
    digit_sum_total = 0
    for (last, remainder, total, copies), ways in states.items():
        if remainder == residue and low <= total <= high and copies == required:
            count += ways
            digit_sum_total += total * ways
    return {'count': count, 'digit_sum_total': digit_sum_total}

def check(answer, facts):
    alphabet = tuple(set(facts['alphabet']))
    length = facts['length']
    count = 0
    digit_sum_total = 0
    for digits in product(alphabet, repeat=length):
        if any(digits[i] == digits[i + 1] for i in range(length - 1)):
            continue
        if digits.count(facts['target_digit']) != facts['target_count']:
            continue
        total = sum(digits)
        if not facts['sum_min'] <= total <= facts['sum_max']:
            continue
        value = sum(digit * pow(10, length - i - 1) for i, digit in enumerate(digits))
        if value % facts['modulus'] != facts['residue']:
            continue
        count += 1
        digit_sum_total += total
    return isinstance(answer, dict) and answer == {'count': count, 'digit_sum_total': digit_sum_total}
